import {createSearchIndex} from './search.js';
import {filteredCatalog,catalogView} from './catalog.js';
import {musicBrainzSearchURL} from './metadata.js';
import {deliveryLabel,connectionSummary,prepareDelivery,runSimulation,cancelDelivery} from './publishing.js';
import {all,put,batch,uid,now,normalize,slug,importSongs,audit,digest,ASSET_FOLDERS,safeURL,canonicalKey,reserveSongs,releaseSong,atomicProduction} from './db.js';
import {STYLES,TEMPLATES,templatePreset,templateBackground,drawCover} from './cover.js';
import {download,exportBackup,readBackup,restoreBackup,editingPackage} from './backup.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STATUS=['Música selecionada','Capa em preparação','Aguardando materiais','Em edição','Pronto para revisão','Pronto para publicar','Publicado','Arquivado','Disponível para nova versão'];
const RIGHTS={confirmed:'Direitos confirmados',library:'Biblioteca de plataforma',pending:'Verificação pendente',unauthorized:'Uso não autorizado',expired:'Licença vencida'};
const TITLES={dashboard:'Hoje',catalog:'Catálogo musical',covers:'Estúdio de capas',production:'Estúdio de produção',publications:'Publicações',archive:'Meu acervo',backup:'Backup e arquivos',settings:'Configurações'};
const channel=('BroadcastChannel' in window)?new BroadcastChannel('gmm-v2-sync'):null;const signal=()=>channel?.postMessage('changed');
let state={songs:[],productions:[],assets:[],publications:[],history:[],settings:[],view:'dashboard',selected:new Set(),search:'',decade:'',sort:'relevance',layout:'list',filters:{},advanced:false,page:0,favorites:false,unused:false,active:null,pubLayout:'list',pubPlatform:'',archiveQuery:'',archiveDecade:'',archivePlatform:'',archiveStatus:'',repertoire:'',cover:null,coverProd:'',bg:null};
let objectURLs=[],renderToken=0,coverTimer,uploading=0;
const songOf=p=>state.songIndex?.get(p.songId)||state.songs.find(s=>s.id===p.songId),assetsOf=id=>state.assetIndex?.get(id)||[],pubsOf=id=>state.pubIndex?.get(id)||[];
const settings=()=>state.settings.find(s=>s.id==='preferences')||{id:'preferences',channel:'Golden Music Memories',dailyProduction:5,dailyTikTok:5,dailyYouTube:5,dailyArchive:5,dailyReuse:0,quality:'image/png'};
const usageOf=s=>{const ps=(state.canonIndex?.get(canonicalKey(s))||[]).filter(p=>!p.cancelled),r=(state.reservations||[]).find(r=>r.id===canonicalKey(s));if(ps.some(p=>pubsOf(p.id).some(pub=>pub.status==='published')))return 'published';if(ps.some(p=>p.status===7))return 'archived';if(ps.some(p=>p.historical||assetsOf(p.id).some(a=>['tiktok','youtube'].includes(a.role))))return 'produced';if(ps.length)return 'inproduction';if(r?.status==='reserved')return 'reserved';if(r?.status==='cancelled')return 'cancelled';return 'available';};
const USAGE={available:'Disponível',reserved:'Reservada',inproduction:'Em produção',produced:'Produzida',published:'Publicada',archived:'Arquivada',cancelled:'Cancelada / liberada'};
const day=iso=>new Date(iso).toLocaleDateString('sv-SE',{timeZone:'America/Sao_Paulo'});const today=()=>day(new Date());
const btn=(action,label,extra='',cls='')=>`<button data-action="${action}" ${extra} class="${cls}">${label}</button>`;
const options=(items,value)=>Object.entries(items).map(([k,v])=>`<option value="${esc(k)}" ${String(value)===k?'selected':''}>${esc(v)}</option>`).join('');
const select=(name,label,items,value)=>`<label class="field">${label}<select name="${name}" id="${name}">${options(items,value)}</select></label>`;
const input=(name,label,value='',type='text',more='')=>`<label class="field">${label}<input name="${name}" id="${name}" type="${type}" value="${esc(value)}" ${more}></label>`;
const empty=text=>`<div class="empty">${text}</div>`;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5500);}
async function refresh(){for(const s of ['songs','productions','assets','publications','history','settings','reservations'])state[s]=await all(s);state.selected=new Set((state.reservations||[]).filter(r=>r.status==='reserved').map(r=>r.songId));state.searchIndex=createSearchIndex(state.songs);state.songIndex=new Map(state.songs.map(s=>[s.id,s]));state.assetIndex=new Map();state.pubIndex=new Map();state.canonIndex=new Map();for(const a of state.assets){const list=state.assetIndex.get(a.productionId)||[];list.push(a);state.assetIndex.set(a.productionId,list);}for(const list of state.assetIndex.values())list.sort((a,b)=>String(a.createdAt||'').localeCompare(String(b.createdAt||''))||a.version-b.version);for(const p of state.publications){const list=state.pubIndex.get(p.productionId)||[];list.push(p);state.pubIndex.set(p.productionId,list);}for(const p of state.productions){const key=canonicalKey(songOf(p)),list=state.canonIndex.get(key)||[];list.push(p);state.canonIndex.set(key,list);}}
function showDialog(html){$('#dialog-body').innerHTML=html;$('#dialog').setAttribute('aria-label',$('#dialog-body h2')?.textContent||'Detalhes');if(!$('#dialog').open)$('#dialog').showModal();}
$('#close-dialog').onclick=()=>$('#dialog').close();
async function route(view,id){await refresh();state.view=view;state.active=id||null;location.hash=view+(id?'/'+id:'');await render();}
function mediaURL(a){const url=URL.createObjectURL(a.blob);objectURLs.push(url);return url;}
async function render(){const token=++renderToken;for(const u of objectURLs)URL.revokeObjectURL(u);objectURLs=[];$('#page-title').textContent=TITLES[state.view]||'Golden Music Memories';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#store-status').textContent='Salvo neste navegador';const views={dashboard:dashboard,catalog:catalog,covers:covers,production:production,publications:publications,archive:archive,backup:backup,settings:config};$('#main').innerHTML=(views[state.view]||dashboard)();if(token!==renderToken)return;bind();if(state.view==='covers')await paint();if(state.view==='backup'||state.view==='settings')storageInfo();}
function dashboard(){const d=today(),ps=state.productions.filter(p=>day(p.createdAt)===d),done=state.assets.filter(a=>['tiktok','youtube'].includes(a.role)&&day(a.createdAt)===d),finished=new Set(done.map(a=>a.productionId)),posted=state.publications.filter(p=>p.publishedAt?.slice(0,10)===d&&p.status==='published');const used=new Set(state.productions.map(p=>p.songId)),pref=settings();return `<p class="lead">Escolha seus clássicos, acompanhe cada etapa e preserve todas as versões.</p><div class="actions">${btn('go-catalog','Escolher músicas')}${btn('go-production','Retomar produção','','secondary')}${btn('go-backup','Exportar backup','','secondary')}</div><div class="stats"><div class="stat gold"><span>PRODUÇÕES INICIADAS HOJE</span><strong>${ps.length} <small>/ ${pref.dailyProduction}</small></strong><progress value="${Math.min(ps.length,pref.dailyProduction)}" max="${pref.dailyProduction}"></progress></div><div class="stat"><span>PRODUÇÕES FINALIZADAS HOJE</span><strong>${finished.size}</strong><small>${done.length} arquivos finais importados</small></div><div class="stat"><span>PUBLICAÇÕES REGISTRADAS HOJE</span><strong>${posted.length}</strong><small>TikTok ${posted.filter(p=>p.platform==='tiktok').length}/${pref.dailyTikTok} · YouTube ${posted.filter(p=>p.platform==='youtube').length}/${pref.dailyYouTube}</small></div><div class="stat"><span>MÚSICAS DISPONÍVEIS</span><strong>${state.songs.filter(s=>usageOf(s)==='available'||usageOf(s)==='cancelled').length}</strong><small>${state.selected.size} reservadas para produção</small></div></div><div class="columns"><section class="panel"><h2>Produção em andamento</h2>${state.productions.filter(p=>p.status<6&&!p.cancelled).slice(-5).reverse().map(p=>`<p>${btn('open-production',esc(songOf(p)?.title),'data-id="'+p.id+'"','link')} <small>· ${STATUS[p.status]} · V${p.version}</small></p>`).join('')||'<p class="muted">Inicie pelo catálogo. Uma produção pode ser salva e concluída individualmente.</p>'}</section><section class="panel"><h2>Seu acervo, em números</h2><p>${state.assets.filter(a=>a.role==='cover').length} capas aprovadas · ${state.assets.filter(a=>['tiktok','youtube'].includes(a.role)).length} vídeos finais</p><p>${state.productions.filter(p=>p.status===7).length} versões arquivadas · ${state.publications.filter(p=>p.status==='planned').length} publicações planejadas</p><p class="note">${state.songs.filter(s=>s.validation==='curated').length} músicas revisadas editorialmente. ${state.songs.filter(s=>s.validation==='metadata_imported').length} registros importados com referência de metadados.</p></section></div><details class="panel"><summary>Desempenho registrado</summary><div class="metrics">${['views','likes','comments','shares'].map((k,i)=>`<div><small>${['Visualizações','Curtidas','Comentários','Compartilhamentos'][i]}</small><h2>${state.publications.reduce((n,p)=>n+Number(p.metrics?.[k]||0),0).toLocaleString('pt-BR')}</h2></div>`).join('')}</div><small>Somente métricas preenchidas pelo operador. Nenhuma coleta automática conectada.</small></details>`;}
function filteredSongs(){return filteredCatalog(state,{usageOf,assetsOf,pubsOf,canonicalKey});}
function catalog(){return catalogView(state,{esc,btn,input,select,options,usageOf,USAGE,filteredSongs,settings});}
function production(){if(!state.active){return `<p class="lead">Retome qualquer etapa. Cada versão mantém seus próprios arquivos e publicações.</p>${state.productions.length?`<div class="grid">${state.productions.slice().reverse().map(p=>{const s=songOf(p);return `<article class="production-card"><span class="tag">V${p.version} · ${STATUS[p.status]}</span><h3>${esc(s.title)}</h3><p>${esc(s.artist)} · ${p.versionYear||s.year}</p><small>${assetsOf(p.id).length} arquivos · ${pubsOf(p.id).length} publicações</small><div class="actions">${btn('open-production','Abrir produção','data-id="'+p.id+'"','small')}</div></article>`;}).join('')}</div>`:empty('Ainda não há produções. Escolha uma música no catálogo.')}`;}
const p=state.productions.find(x=>x.id===state.active);if(!p)return empty('Produção não encontrada.');const s=songOf(p),files=assetsOf(p.id);return `<div class="breadcrumbs">${btn('go-production','← Todas as produções','','link')} / ${esc(p.id.slice(0,8))} · V${p.version}</div><div class="section-head"><div><h2>${esc(s.title)}</h2><p class="muted">${esc(s.artist)} · ${s.year} <small>(${esc(s.yearMeaning||'ano informado')})</small></p></div><div class="actions">${btn('cover-production','Criar capa','data-id="'+p.id+'"')}${btn('new-version','Criar nova versão','data-id="'+p.id+'"','secondary')}${btn('cancel-production','Cancelar / liberar','data-id="'+p.id+'"','secondary')}</div></div><div class="steps">${['Escolha','Capa','Mídias','Edição','Revisão','Publicação','Acervo'].map((v,i)=>`<span class="${i<=Math.min(p.status,6)?'on':''}">${i+1}. ${v}</span>`).join('')}</div><form id="production-form" class="panel"><div class="form-grid">${select('stage','Etapa',Object.fromEntries(STATUS.map((v,i)=>[i,v])),p.status)}${input('versionYear','Ano da versão usada na capa',p.versionYear||s.year,'number','min="1970" max="2100" required')}${input('plannedDate','Data de produção planejada',p.plannedDate||today(),'date')}<label class="field">Observações / roteiro<textarea name="notes" id="notes">${esc(p.notes||'')}</textarea></label></div><small>As alterações são salvas automaticamente neste navegador.</small><div class="actions">${btn('save-production','Salvar agora','','small')}${btn('export-production','Exportar pacote para edição','data-id="'+p.id+'"','secondary small')}${btn('folder-manifest','Ver estrutura de pastas','data-id="'+p.id+'"','secondary small')}</div></form><section class="panel"><h2>Direitos e comprovação</h2><p class="muted">Permissões independentes por ativo, plataforma, território e prazo.</p><form id="rights-form"><div class="form-grid">${['recording','composition','visual','tiktok','youtube','commercial'].map((k,i)=>select('rights-'+k,['Gravação musical','Composição / sincronização','Clipe e imagens','Uso no TikTok','Uso no YouTube','Monetização comercial'][i],RIGHTS,p.rights?.[k]||'pending')).join('')}${input('licenseUntil','Validade da licença',p.licenseUntil||'','date')}${input('territory','Territórios autorizados',p.territory||'')}${input('licenseSource','Fonte / autorização',p.licenseSource||'','url')}<label class="field">Decisão do operador<textarea id="operatorNote" name="operatorNote">${esc(p.operatorNote||'')}</textarea></label></div>${btn('save-rights','Salvar direitos','','small')}</form><small>“Biblioteca de plataforma” não transfere a licença para outro aplicativo. Documentos podem ser anexados abaixo.</small></section><section class="panel"><div class="section-head"><h2>Materiais e arquivos</h2>${btn('approve-review','Registrar revisão','data-id="'+p.id+'"','secondary small')} ${btn('rights-check','Conferir pendências','data-id="'+p.id+'"','secondary small')}</div><label class="field">Tipo do material<select id="asset-role">${options({cover:'Capa',audio:'Áudio autorizado',clip:'Clipe autorizado',image:'Imagem complementar',project:'Projeto CapCut / auxiliar',tiktok:'Vídeo final TikTok',youtube:'Vídeo final YouTube',text:'Legenda / descrição',license:'Licença / comprovante'},'image')}</select></label><div class="dropzone" id="dropzone"><label>Arraste arquivos aqui ou <input id="asset-upload" type="file" multiple></label><small>MP4 final: até 500 MB por arquivo, sujeito ao espaço disponível no navegador.</small></div>${files.map(assetRow).join('')||empty('Nenhum arquivo anexado. As novas versões preservam os arquivos anteriores.')}</section><section class="panel"><h2>Preparar publicações</h2><p>Os fluxos do TikTok e do YouTube possuem arquivos e metadados independentes.</p><div class="actions">${btn('edit-publication','Preparar TikTok','data-id="'+p.id+'" data-platform="tiktok"')}${btn('edit-publication','Preparar YouTube','data-id="'+p.id+'" data-platform="youtube"','secondary')}</div>${pubsOf(p.id).map(pub=>`<p>${esc(pub.platform)} · ${esc(pub.status)} · ${esc(pub.title)}</p>`).join('')}</section>`;}
function assetRow(a){let preview='';const url=mediaURL(a);if(a.type.startsWith('image/'))preview=`<img src="${url}" alt="${esc(a.originalName||a.name)}">`;if(a.type.startsWith('video/'))preview=`<video controls preload="metadata" src="${url}"></video>`;if(a.type.startsWith('audio/'))preview=`<audio controls preload="metadata" src="${url}"></audio>`;return `<div class="asset">${preview}<div class="info"><p><b>${esc(a.originalName||a.name)}</b></p><small>${esc(ASSET_FOLDERS[a.role]||a.role)} · V${a.version} · ${(a.size/1048576).toFixed(2)} MB<br>${new Date(a.createdAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})} · ${esc(RIGHTS[a.rights]||RIGHTS.pending)}</small></div>${a.coverConfig?btn('recover-cover','Editar esta versão','data-id="'+a.id+'"','secondary small'):''}${btn('download-asset','Baixar','data-id="'+a.id+'"','secondary small')}${btn('asset-rights','Licença','data-id="'+a.id+'"','secondary small')}</div>`;}
function covers(){if(!state.cover){const draft=state.settings.find(s=>s.id==='coverDraft');state.cover=draft?.config||{title:'Take On Me',artist:'a-ha',year:'1985',style:'cassette',format:'vertical',font:104,x:.085,y:.23,text:'#f8f0df',accent:'#edc283',safe:false};state.coverProd=draft?.productionId||state.coverProd;}const c=state.cover;return `<p class="lead">Templates locais sem custo de API. Salve cada arte aprovada como uma nova versão da produção.</p><div class="template-family" aria-label="Família oficial de templates">${Object.entries(TEMPLATES).map(([id,t])=>`<button type="button" data-action="select-template" data-id="${id}" aria-pressed="${c.style===id}" class="template-card ${c.style===id?'selected':''}"><img src="${t.asset}" alt="" loading="lazy"><span>${esc(t.name)}</span></button>`).join('')}</div><div class="editor"><section class="panel"><form id="cover-form">${select('cover-production','Produção associada',{'':'Escolha uma produção',...Object.fromEntries(state.productions.map(p=>[p.id,songOf(p).title+' · V'+p.version]))},state.coverProd)}${input('cover-title','Nome da música',c.title)}${input('cover-artist','Artista',c.artist)}<div class="form-grid">${input('cover-year','Ano da versão',c.year)}${select('cover-style','Estilo',Object.fromEntries(Object.entries(STYLES).map(([k,v])=>[k,v[0]])),c.style)}${select('cover-format','Formato',{vertical:'TikTok / Shorts · 1080×1920',horizontal:'YouTube · 1280×720'},c.format)}${select('cover-family','Tipografia',{Arial:'Arial','Georgia':'Georgia','Verdana':'Verdana'},c.family||'Arial')}${input('cover-text','Cor do texto',c.text,'color')}${input('cover-accent','Cor de destaque',c.accent,'color')}${input('cover-font','Tamanho do título',c.font,'range','min="40" max="160"')}${input('cover-x','Posição horizontal',c.x,'range','min="0.04" max="0.35" step="0.01"')}${input('cover-y','Posição vertical',c.y,'range','min="0.15" max="0.55" step="0.01"')}</div><label class="field">Imagem própria de fundo<input id="cover-background" type="file" accept="image/*"></label><label><input id="cover-safe" type="checkbox" ${c.safe?'checked':''}> Mostrar margens de referência na prévia</label><p class="muted"><small>As margens não são exportadas. Nos Shorts, a plataforma pode permitir apenas selecionar um quadro do vídeo.</small></p></form><div class="actions">${btn('variation','Outra variação','','secondary')}${btn('download-cover','Baixar PNG')}${btn('download-jpg','Baixar JPG','','secondary')}${btn('approve-cover','Aprovar e guardar','','secondary')}</div><p id="cover-feedback" class="muted"></p></section><div class="preview"><canvas id="cover-canvas" width="1080" height="1920" aria-label="Prévia da capa"></canvas><small>Produção independente · identidade preservada</small></div></div>`;}
function publications(){const pubs=state.publications.filter(p=>!state.pubPlatform||p.platform===state.pubPlatform);let body='';if(state.pubLayout==='kanban'){body=`<div class="kanban">${STATUS.map((label,i)=>`<section class="lane"><h3>${label}</h3>${state.productions.filter(p=>p.status===i).map(p=>`<article><b>${esc(songOf(p).title)}</b><p>V${p.version}</p>${pubsOf(p.id).filter(pub=>!state.pubPlatform||pub.platform===state.pubPlatform).map(pub=>`<small>${pub.platform} · ${esc(pub.plannedAt?.slice(0,10)||'Sem data')}</small><br>`).join('')}${btn('open-production','Abrir','data-id="'+p.id+'"','small secondary')}</article>`).join('')||'<small>Sem produções</small>'}</section>`).join('')}</div>`;}else if(state.pubLayout==='calendar'){const month=state.calendarMonth||today().slice(0,7);const [year,m]=month.split('-').map(Number),days=new Date(year,m,0).getDate();body=`${input('calendar-month','Mês',month,'month')}<div class="calendar">${Array.from({length:days},(_,i)=>{const day=month+'-'+String(i+1).padStart(2,'0');return `<div class="day"><b>${i+1}</b>${pubs.filter(p=>(p.plannedAt||'').slice(0,10)===day).map(p=>`<article>${btn('edit-pub-id',esc(p.title),'data-id="'+p.id+'"','link')}<br>${esc(p.platform)} · ${esc(p.status)}</article>`).join('')}</div>`;}).join('')}</div>`;}else body=pubs.length?`<div class="table-wrap"><table><thead><tr><th>Música / plataforma</th><th>Planejada</th><th>Situação / arquivo</th><th>Ações</th></tr></thead><tbody>${pubs.map(p=>`<tr><td><b>${esc(p.title)}</b><br>${esc(p.platform)}</td><td>${esc(p.plannedAt?.replace('T',' ')||'Sem data')}</td><td>${esc(p.status)}<br><small>${p.finalAssetId?'Vídeo associado':'Sem vídeo final'}</small></td><td><div class="actions">${btn('edit-pub-id','Editar','data-id="'+p.id+'"','small')}${btn('copy-publication','Copiar descrição','data-id="'+p.id+'"','secondary small')}${safeURL(p.url)?`<a href="${esc(safeURL(p.url))}" target="_blank" rel="noopener noreferrer">Abrir postagem</a>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Prepare uma publicação dentro de uma produção.');return `${deliveryPanel(pubs)}<p class="lead">Planejamento e registro manual assistido. Agendar aqui não envia conteúdo às plataformas.</p><div class="filters"><select id="pub-platform" aria-label="Plataforma">${options({'':'Todas as plataformas',tiktok:'TikTok',youtube:'YouTube'},state.pubPlatform)}</select>${btn('pub-list','Lista','','secondary')}${btn('pub-kanban','Kanban','','secondary')}${btn('pub-calendar','Calendário','','secondary')}</div>${body}`;}
function archive(){let items=state.assets.filter(a=>['tiktok','youtube'].includes(a.role));items=items.filter(a=>{const p=state.productions.find(p=>p.id===a.productionId),s=songOf(p);return normalize(`${s.title} ${s.artist} ${a.createdAt}`).includes(normalize(state.archiveQuery))&&(!state.archiveDecade||s.decade==state.archiveDecade)&&(!state.archivePlatform||a.role===state.archivePlatform)&&(!state.archiveStatus||(state.archiveStatus==='unpublished'?!pubsOf(p.id).some(pub=>pub.status==='published'):pubsOf(p.id).some(pub=>pub.status==='published')));});return `<p class="lead">Vídeos finais importados e suas versões. Nenhum arquivo anterior é substituído ao criar uma nova versão.</p><div class="filters"><input type="search" id="archive-search" value="${esc(state.archiveQuery)}" placeholder="Música, artista ou data" aria-label="Pesquisar acervo"><select id="archive-decade" aria-label="Década">${options({'':'Todas as décadas',1970:'Anos 70',1980:'Anos 80',1990:'Anos 90',2000:'Anos 2000'},state.archiveDecade)}</select><select id="archive-platform" aria-label="Plataforma">${options({'':'Todas as plataformas',tiktok:'TikTok',youtube:'YouTube'},state.archivePlatform)}</select><select id="archive-status" aria-label="Publicação">${options({'':'Todas as situações',published:'Publicados',unpublished:'Não publicados'},state.archiveStatus)}</select></div>${items.length?items.map(a=>{const p=state.productions.find(p=>p.id===a.productionId),s=songOf(p);return `<section class="panel"><div class="section-head"><h3>${esc(s.title)} — ${esc(s.artist)} · V${p.version}</h3><div class="actions">${btn('open-production','Ver produção','data-id="'+p.id+'"','secondary small')}${btn('new-version','Criar nova versão','data-id="'+p.id+'"','small')}</div></div>${assetRow(a)}</section>`;}).join(''):empty('Nenhum vídeo final encontrado. Importe um MP4 no Estúdio de produção.')}`;}
function backup(){return `<p class="lead">Leve registros e arquivos juntos para outro computador. A restauração verifica referências e integridade dos arquivos antes de substituir os dados locais.</p><div class="columns"><section class="panel"><h2>Backup completo</h2><p>Inclui catálogo, produções, mídias, direitos, publicações, métricas e histórico, com verificação SHA-256.</p>${btn('export-backup','Baixar backup ZIP')}<p class="note">Copie esse ZIP para seu Google Drive e para um armazenamento externo. Não há envio automático.</p></section><section class="panel"><h2>Restaurar backup</h2><p>Escolha um backup exportado pelo painel. O conteúdo atual só será substituído depois da validação e confirmação.</p><input type="file" id="restore-input" accept=".zip" aria-label="Selecionar backup ZIP"><p id="restore-feedback"></p></section></div><section class="panel"><h2>Google Drive · estrutura organizada</h2><p>O pacote de cada produção usa pastas padronizadas para capas, áudios, clipes, CapCut, finais e comprovantes.</p>${btn('drive-structure','Baixar estrutura de pastas','','secondary')}<p class="muted">Integração OAuth não configurada. Exporte os pacotes e faça upload manual no Drive.</p><div id="storage-info"></div></section><section class="panel"><h2>Exportar controles</h2>${btn('export-records','Baixar catálogo e controle JSON','','secondary')} <small>Este arquivo contém os registros; para incluir mídias, use o backup completo.</small></section>`;}
function config(){const p=settings();return `<p class="lead">As funções essenciais operam sem APIs pagas. Nenhuma credencial administrativa é solicitada ou armazenada neste painel.</p><form id="settings-form" class="panel"><h2>Rotina de produção</h2><div class="form-grid">${input('channel','Nome do canal',p.channel)}${input('dailyProduction','Meta diária de produções',p.dailyProduction,'number','min="1"')}${input('dailyTikTok','Meta diária TikTok',p.dailyTikTok,'number','min="0"')}${input('dailyYouTube','Meta diária YouTube',p.dailyYouTube,'number','min="0"')}${input('dailyArchive','Meta diária de arquivamentos',p.dailyArchive??5,'number','min="0"')}${input('dailyReuse','Meta diária de novas versões',p.dailyReuse??0,'number','min="0"')}${select('quality','Formato de imagem padrão',{'image/png':'PNG · sem perdas','image/jpeg':'JPG · qualidade 92%'},p.quality)}</div><button type="submit">Salvar configurações</button></form><section class="panel"><h2>Armazenamento e integrações</h2><p><span class="tag">Operacional</span> Banco local IndexedDB · arquivos neste navegador · backup ZIP</p><p><span class="tag">Fluxo externo assistido</span> Canva Pro: exporte as músicas selecionadas em CSV para Criação em lote e devolva as artes à produção.</p><p><span class="tag warn">Pendente</span> Google Drive: requer configuração OAuth e homologação.</p><p><span class="tag warn">Pendente</span> Supabase: requer ambiente dedicado, autenticação e migração testada.</p><p><span class="tag warn">Pendente</span> Provedor de imagens por API: requer backend, credenciais e aprovação de custo. A família oficial de sete templates e os estilos adicionais funcionam sem API.</p><p><span class="tag warn">Manual</span> CapCut, TikTok e YouTube: pacotes e metadados; sem API de publicação conectada.</p><div id="storage-info"></div>${btn('persist-storage','Solicitar armazenamento persistente','','secondary')}</section><section class="panel"><h2>Metadados e privacidade</h2><p>${state.songs.length} músicas cadastradas · ${state.songs.filter(s=>s.validation==='curated').length} revisadas editorialmente.</p><p>Dados importados do MusicBrainz são comunitários e mantêm referência da gravação. O ano informado não garante a data original da composição. Direitos de uso continuam pendentes.</p><p>Arquivos enviados ficam no navegador e não são enviados ao repositório público. Use o backup ZIP para levar seus dados a outro computador; não há sincronização automática.</p></section>`;}
async function storageInfo(){try{const e=await navigator.storage.estimate();if($('#storage-info'))$('#storage-info').textContent=`Espaço usado: ${(e.usage/1048576).toFixed(1)} MB · cota estimada: ${(e.quota/1073741824).toFixed(1)} GB. Faça backups regulares.`;}catch{}}
async function createProduction(songId,previous){const p={id:uid(),songId,version:previous?previous.version+1:1,parentId:previous?.id||null,status:0,createdAt:now(),updatedAt:now(),plannedDate:today(),versionYear:previous?.versionYear||state.songs.find(s=>s.id===songId).year,rights:{recording:'pending',composition:'pending',visual:'pending',tiktok:'pending',youtube:'pending',commercial:'pending'},notes:previous?.notes||''};const versions=state.productions.filter(x=>x.songId===songId);p.version=Math.max(0,...versions.map(x=>x.version))+1;await atomicProduction(state.songs.find(s=>s.id===songId),p,!!previous);signal();if(previous){for(const a of assetsOf(previous.id)){const {id,...rest}=a;await put('assets',{...rest,id:uid(),productionId:p.id,rights:'pending',inheritedFrom:id,createdAt:now()});}}await audit('production_created',p.id,previous?'Nova versão de '+previous.id:'');await refresh();return p;}
async function uploadFiles(files,role,pid=state.active){uploading++;toast('Salvando arquivos…');const toggle=()=>document.querySelectorAll('[data-action="approve-review"],[data-action="new-version"],[data-action="export-production"],#asset-upload').forEach(b=>b.disabled=uploading>0);toggle();try{return await processUploads(files,role,pid);}finally{uploading--;toggle();}}
async function processUploads(files,role,pid=state.active){if(!pid)throw Error('Escolha uma produção.');const p=state.productions.find(x=>x.id===pid);for(const file of files){if(file.size>500*1048576)throw Error('Arquivo acima de 500 MB. Use um arquivo menor ou armazenamento externo.');if(['tiktok','youtube'].includes(role)&&!(/\.mp4$/i.test(file.name)&&file.type.startsWith('video/')))throw Error('Para versão final, selecione um vídeo MP4.');const hash=await digest(file);if(state.assets.some(a=>a.productionId===pid&&a.hash===hash&&a.role===role)){toast('Arquivo idêntico já existe nesta produção.');continue;}const version=state.assets.filter(a=>a.productionId===pid&&a.role===role).length+1,id=uid(),ext=file.name.split('.').pop().replace(/[^a-zA-Z0-9]/g,'').slice(0,10),name=`GMM_${pid.slice(0,8)}_${role}_V${version}_${slug(file.name.replace(/\.[^.]+$/,''))}_${hash.slice(0,8)}.${ext||'bin'}`;await put('assets',{id,productionId:pid,songId:p.songId,role,version,name,originalName:file.name,type:file.type||'application/octet-stream',size:file.size,hash,blob:file,rights:'pending',createdAt:now()});await refresh();}const latest=(await all('productions')).find(x=>x.id===pid);latest.approval=null;await put('productions',latest);await audit('media_imported',pid,role);}
async function paint(){const canvas=$('#cover-canvas');if(!canvas)return;const cfg=state.cover;let bg=state.bg;if(!bg&&cfg.backgroundAssetId){const a=state.assets.find(a=>a.id===cfg.backgroundAssetId);if(a)bg=mediaURL(a);}if(!bg)bg=templateBackground(cfg.style);await drawCover(canvas,cfg,bg);}
function readCover(){const map={title:'cover-title',artist:'cover-artist',year:'cover-year',style:'cover-style',format:'cover-format',family:'cover-family',text:'cover-text',accent:'cover-accent',font:'cover-font',x:'cover-x',y:'cover-y'};for(const [k,v]of Object.entries(map))if($('#'+v))state.cover[k]=$('#'+v).value;state.cover.safe=$('#cover-safe').checked;state.coverProd=$('#cover-production').value;}
async function coverBlob(type='image/png'){const canvas=document.createElement('canvas');const c={...state.cover,safe:false};let bg=state.bg;if(!bg&&c.backgroundAssetId){const a=state.assets.find(a=>a.id===c.backgroundAssetId);if(a)bg=mediaURL(a);}if(!bg)bg=templateBackground(c.style);await drawCover(canvas,c,bg);return new Promise(r=>canvas.toBlob(r,type,.92));}
async function saveProduction(){const p=state.productions.find(p=>p.id===state.active);if(!p||!$('#production-form'))return;const previous=p.status;p.status=Number($('#stage').value);if(p.status===5&&!p.approval){p.status=previous;$('#stage').value=String(previous);throw Error('Registre a revisão da capa e do vídeo antes de marcar Pronto para publicar.');}p.notes=$('#notes').value;p.plannedDate=$('#plannedDate').value;p.versionYear=Number($('#versionYear').value);if(!p.versionYear||p.versionYear<1970||p.versionYear>2100)return;p.updatedAt=now();await put('productions',p);if(previous!==p.status)await audit('production_stage_changed',p.id,STATUS[p.status]);$('#store-status').textContent='Alterações salvas';}
function bind(){bindCatalog();for(const [id,key]of [['repertoire-filter','repertoire'],['decade-filter','decade'],['sort-filter','sort'],['pub-platform','pubPlatform'],['archive-decade','archiveDecade'],['archive-platform','archivePlatform'],['archive-status','archiveStatus'],['calendar-month','calendarMonth']])if($('#'+id))$('#'+id).onchange=e=>{state[key]=e.target.value;state.page=0;render();};for(const [id,key]of [['favorites-only','favorites'],['unused-only','unused']])if($('#'+id))$('#'+id).onchange=e=>{state[key]=e.target.checked;state.page=0;render();};document.querySelectorAll('[data-song-select]').forEach(c=>c.onchange=()=>{guarded(async()=>{const song=state.songs.find(s=>s.id===c.dataset.songSelect);if(c.checked)await reserveSongs([song]);else await releaseSong(song);await refresh();signal();render();});});if($('#archive-search'))$('#archive-search').onchange=e=>{state.archiveQuery=e.target.value;render();};if($('#production-form')){$('#production-form').onsubmit=e=>e.preventDefault();$('#production-form').oninput=()=>saveProduction().catch(fail);}if($('#rights-form')){$('#rights-form').onsubmit=e=>e.preventDefault();$('#rights-form').onchange=()=>guarded(async()=>{const p=state.productions.find(p=>p.id===state.active);for(const k of ['recording','composition','visual','tiktok','youtube','commercial'])p.rights[k]=$('#rights-'+k).value;for(const k of ['licenseUntil','territory','licenseSource','operatorNote'])p[k]=$('#'+k).value;p.updatedAt=now();p.approval=null;await put('productions',p);});}if($('#asset-upload'))$('#asset-upload').onchange=async e=>{await guarded(async()=>{await uploadFiles(e.target.files,$('#asset-role').value);await refresh();render();toast('Materiais salvos.');});};if($('#dropzone')){const z=$('#dropzone');z.ondragover=e=>{e.preventDefault();z.classList.add('over');};z.ondragleave=()=>z.classList.remove('over');z.ondrop=e=>{e.preventDefault();guarded(async()=>{await uploadFiles(e.dataTransfer.files,$('#asset-role').value);await refresh();render();toast('Materiais salvos.');});};}if($('#cover-form')){$('#cover-form').onsubmit=e=>e.preventDefault();$('#cover-form').oninput=()=>{readCover();clearTimeout(coverTimer);coverTimer=setTimeout(()=>guarded(async()=>{await put('settings',{id:'coverDraft',config:state.cover,productionId:state.coverProd});await paint();}),180);};$('#cover-style').onchange=()=>guarded(()=>selectTemplate($('#cover-style').value));$('#cover-production').onchange=()=>{const p=state.productions.find(p=>p.id===$('#cover-production').value);if(p){const s=songOf(p);state.cover={...state.cover,title:s.title,artist:s.artist,year:p.versionYear||s.year};state.coverProd=p.id;render();}};$('#cover-background').onchange=e=>guarded(async()=>{const f=e.target.files[0];if(!f||!f.type.startsWith('image/'))throw Error('Escolha uma imagem.');if(f.size>20*1048576)throw Error('Imagem acima de 20 MB.');if(!state.coverProd)throw Error('Associe uma produção para preservar o fundo enviado.');await uploadFiles([f],'background',state.coverProd);const a=assetsOf(state.coverProd).filter(a=>a.role==='background').at(-1);state.cover.backgroundAssetId=a.id;state.bg=null;await put('settings',{id:'coverDraft',config:state.cover,productionId:state.coverProd});await paint();toast('Fundo salvo na produção.');});}if($('#restore-input'))$('#restore-input').onchange=e=>guarded(async()=>{const f=e.target.files[0];if(!f)return;$('#restore-feedback').textContent='Validando arquivos e referências…';const data=await readBackup(f);if(!confirm(`Backup válido: ${data.tables.songs.length} músicas e ${data.tables.assets.length} arquivos. Substituir TODOS os dados deste navegador? Faça um backup antes se necessário.`)){$('#restore-feedback').textContent='Restauração cancelada; dados preservados.';return;}await restoreBackup(data);await refresh();state.selected=new Set();state.cover=null;state.active=null;await route('dashboard');toast('Backup restaurado e integridade verificada.');});if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{const f=new FormData(e.target),v={...settings()};for(const [k,val]of f){if(k.startsWith('daily')){const n=Number(val);if(!Number.isSafeInteger(n)||n<(k==='dailyProduction'?1:0))throw Error('As metas devem ser números inteiros válidos, sem valores negativos.');v[k]=n;}else v[k]=val;}await put('settings',v);await refresh();toast('Configurações salvas.');});};}
function fail(e){console.error(e);toast(e?.name==='QuotaExceededError'?'Sem espaço no navegador. Exporte um backup e libere espaço antes de continuar.':e.message||'Não foi possível concluir a operação.');}
async function guarded(fn){try{await fn();}catch(e){fail(e);}}
const actions={};
for(const name of ['catalog','production','backup','covers','archive','publications','settings','dashboard'])actions['go-'+name]=()=>route(name);
actions['toggle-layout']=()=>{state.layout=state.layout==='cards'?'list':'cards';render();};
actions['favorite']=async b=>{const s=state.songs.find(s=>s.id===b.dataset.id);s.favorite=!s.favorite;await put('songs',s);await refresh();render();};
actions['start-song']=async b=>{const s=state.songs.find(s=>s.id===b.dataset.id);const related=state.productions.find(p=>!p.cancelled&&canonicalKey(songOf(p))===canonicalKey(s));let previous;if(related){if(!confirm('Há uma produção da mesma música ou de uma versão semelhante. Criar explicitamente uma nova versão vinculada, preservando o histórico?'))return;previous=related;}const p=await createProduction(s.id,previous);route('production',p.id);};
actions['open-production']=b=>route('production',b.dataset.id);
actions['create-selected']=async()=>{if(!state.selected.size)throw Error('Selecione pelo menos uma música.');for(const id of state.selected)await createProduction(id);await refresh();signal();route('production');toast('Produções individuais iniciadas.');};
actions['suggest-five']=async()=>{await refresh();const count=Math.max(0,Number(settings().dailyProduction)-state.selected.size);const candidates=state.songs.filter(s=>!(state.reservations||[]).some(r=>r.id===canonicalKey(s)&&r.status!=='cancelled')&&!state.productions.some(p=>p.songId===s.id&&!p.cancelled));const unique=new Map(candidates.map(s=>[canonicalKey(s),s]));const chosen=[...unique.values()].sort(()=>Math.random()-.5).slice(0,count);const added=await reserveSongs(chosen);await refresh();signal();render();toast(`${added} músicas inéditas reservadas. A playlist está salva.`);};
actions['unselect-song']=async b=>{await releaseSong(state.songs.find(s=>s.id===b.dataset.id));await refresh();signal();render();};
actions['prev-page']=()=>{state.page=Math.max(0,state.page-1);render();};actions['next-page']=()=>{if((state.page+1)*30<filteredSongs().length)state.page++;render();};
actions['manual-song']=()=>{showDialog(`<h2>Adicionar música real</h2><form id="song-form">${input('title','Título','','text','required')}${input('artist','Artista','','text','required')}${input('year','Ano original informado','','number','min="1970" max="2009" required')}${input('genre','Gênero')}${input('country','País de origem, se verificado')}${input('source','URL da fonte','','url')}<button type="submit">Cadastrar música</button></form>`);$('#song-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{const s=Object.fromEntries(new FormData(e.target));const result=await importSongs([s]);if(!result.added)throw Error('Música já cadastrada (artista e título).');$('#dialog').close();await refresh();render();toast('Música cadastrada com curadoria pendente.');});};};
actions['song-info']=b=>{const s=state.songs.find(s=>s.id===b.dataset.id);showDialog(`<h2>${esc(s.title)}</h2><p>${esc(s.artist)} · ${s.year} · ${s.decade}</p><p>${esc(s.yearMeaning||'Ano informado pelo operador; conferir fonte.')}</p><p>Gênero: ${esc(s.genre||'Não informado')} · País: ${esc(s.country||'Não informado')}</p><p>${safeURL(s.source)?`<a target="_blank" rel="noopener noreferrer" href="${esc(safeURL(s.source))}">Consultar fonte de metadados</a>`:'Sem referência de fonte'}</p><p>ID: ${esc(s.sourceId||s.id)}</p><p>Validação: ${s.validation==='curated'?'Revisão editorial concluída':'Revisão editorial pendente'}. Direitos: pendentes por padrão.</p>${btn('curate-song','Registrar revisão editorial','data-id="'+s.id+'"','secondary')} ${btn('legacy-use','Registrar uso anterior','data-id="'+s.id+'"','secondary')}<h3>Histórico de uso</h3>${state.productions.filter(p=>canonicalKey(songOf(p))===canonicalKey(s)).map(p=>`<p>V${p.version} · ${p.cancelled?'Cancelada':STATUS[p.status]} · ${p.createdAt.slice(0,10)}</p>`).join('')||'<p>Sem produção anterior.</p>'}<p><small>Marque somente após conferir título, artista, versão e ano na fonte.</small></p>`);};
actions['legacy-use']=b=>{const song=state.songs.find(s=>s.id===b.dataset.id);showDialog(`<h2>Registrar uso anterior</h2><p>${esc(song.title)} — ${esc(song.artist)}</p><form id="legacy-form">${input('legacy-date','Data efetiva',today(),'date','required')}${select('legacy-platform','Uso anterior',{produced:'Produzida (sem publicação)',tiktok:'Publicada no TikTok',youtube:'Publicada no YouTube'},'produced')}${input('legacy-url','Link da publicação, se houver','','url')}<p class="muted">Este registro impede a sugestão como inédita. Não cria um vídeo nem comprova direitos.</p><button type="submit">Registrar histórico</button></form>`);$('#legacy-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{const platform=$('#legacy-platform').value,url=$('#legacy-url').value,date=$('#legacy-date').value;if(platform!=='produced'&&!safeURL(url))throw Error('Informe o link da publicação anterior.');if(url&&state.publications.some(pub=>pub.url===url))throw Error('Link já registrado.');const p=await createProduction(song.id);p.historical=true;p.createdAt=date+'T12:00:00.000Z';p.status=platform==='produced'?4:6;await put('productions',p);if(platform!=='produced')await put('publications',{id:uid(),productionId:p.id,platform,status:'published',title:song.title+' — '+song.artist,url,publishedAt:date+'T12:00',historical:true,metrics:{},createdAt:now()});await audit('legacy_use_registered',p.id);$('#dialog').close();await refresh();render();toast('Uso anterior registrado e repertório reservado.');});};};
actions['curate-song']=async b=>{const s=state.songs.find(s=>s.id===b.dataset.id);if(!safeURL(s.source))throw Error('Inclua uma fonte verificável antes de concluir a curadoria.');if(!confirm('Você conferiu título, artista, versão e ano na fonte?'))return;s.validation='curated';s.reviewedAt=now();await put('songs',s);await audit('song_reviewed',s.id);$('#dialog').close();await refresh();render();};
actions['import-songs']=()=>{showDialog(`<h2>Importar catálogo</h2><p>Selecione JSON com uma lista de músicas (ou objeto com songs), ou CSV UTF-8 com cabeçalho: title,artist,year,genre,country,source. Todos os registros são validados antes de gravar.</p><input type="file" id="song-import" aria-label="Importar músicas JSON ou CSV" accept=".json,.csv"><p id="import-feedback"></p><details><summary>Exemplo de JSON</summary><pre class="code">[{"title":"Título real","artist":"Artista real","year":1985,"source":"https://fonte"}]</pre></details>`);$('#song-import').onchange=e=>guarded(async()=>{const f=e.target.files[0];if(!f)return;let rows;if(f.name.endsWith('.json')){const d=JSON.parse(await f.text());rows=Array.isArray(d)?d:d.songs;}else rows=parseCSV(await f.text());if(!Array.isArray(rows))throw Error('Arquivo sem lista de músicas.');const ambiguous=rows.filter(row=>state.songs.some(old=>canonicalKey(old)===canonicalKey(row)&&(old.year!==Number(row.year)||(old.sourceId&&row.sourceId&&old.sourceId!==row.sourceId))));if(ambiguous.length&&!confirm(`${ambiguous.length} registros podem ser versões ou cadastros semelhantes. Manter separados para revisão editorial?`))return;const r=await importSongs(rows);$('#import-feedback').textContent=`${r.added} cadastradas; ${r.duplicates} duplicadas ignoradas.`;await refresh();});};
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('CSV com aspas não fechadas.');if(field||row.length){row.push(field);rows.push(row);}const headers=(rows.shift()||[]).map(s=>s.replace(/^\uFEFF/,'').trim());return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])));}
actions['save-production']=async()=>{await saveProduction();toast('Produção salva.');};
actions['save-rights']=async()=>{const p=state.productions.find(p=>p.id===state.active);for(const k of ['recording','composition','visual','tiktok','youtube','commercial'])p.rights[k]=$('#rights-'+k).value;for(const k of ['licenseUntil','territory','licenseSource','operatorNote'])p[k]=$('#'+k).value;if(p.licenseSource&&!safeURL(p.licenseSource))throw Error('Use uma URL http ou https para a autorização.');p.updatedAt=now();p.approval=null;await put('productions',p);await audit('rights_updated',p.id);toast('Direitos e decisão registrados.');};
actions['approve-review']=async b=>{if(uploading)throw Error('Aguarde o término da importação antes da revisão.');const p=state.productions.find(p=>p.id===b.dataset.id),files=assetsOf(p.id),finals=files.filter(a=>['tiktok','youtube'].includes(a.role));if(!files.some(a=>a.role==='cover')||!finals.length)throw Error('Associe uma capa e pelo menos um vídeo final antes da revisão.');if(!confirm('Você assistiu ao vídeo, conferiu capa, textos e permissões? Registrar revisão editorial?'))return;p.approval={at:now(),rightsConfirmed:rightsIssues(p).length===0,files:finals.map(a=>({id:a.id,hash:a.hash}))};await put('productions',p);await audit('editorial_review_approved',p.id);toast('Revisão registrada. Novos arquivos exigem nova revisão.');};
actions['rights-check']=b=>{const p=state.productions.find(p=>p.id===b.dataset.id),issues=rightsIssues(p);showDialog(`<h2>Conferência da produção</h2>${issues.length?'<ul>'+issues.map(i=>'<li>'+esc(i)+'</li>').join('')+'</ul>':'<p>Sem pendências nos campos preenchidos. Isto não certifica licença ou monetização.</p>'}<p>Arquivos: ${assetsOf(p.id).length}. Capas: ${assetsOf(p.id).filter(a=>a.role==='cover').length}.</p>`);};
function rightsIssues(p,platform){const issues=[];if(p.licenseUntil&&p.licenseUntil<today())issues.push('A licença informada está vencida.');for(const [k,v]of Object.entries(p.rights||{})){if(platform&&['tiktok','youtube'].includes(k)&&k!==platform)continue;if(['pending','unauthorized','expired'].includes(v))issues.push(`${{recording:'Gravação',composition:'Composição',visual:'Imagens',tiktok:'TikTok',youtube:'YouTube',commercial:'Uso comercial'}[k]}: ${RIGHTS[v]}.`);}return issues;}
actions['download-asset']=b=>{const a=state.assets.find(a=>a.id===b.dataset.id);download(a.blob,a.name);};
actions['asset-rights']=b=>{const a=state.assets.find(a=>a.id===b.dataset.id);showDialog(`<h2>Licença do material</h2><p>${esc(a.originalName||a.name)}</p><form id="asset-right-form">${select('assetRights','Situação',RIGHTS,a.rights)}${input('assetSource','Fonte ou licença',a.source||'','url')}${input('assetUntil','Validade',a.until||'','date')}${input('assetTerritory','Territórios',a.territory||'')}<button type="submit">Salvar licença</button></form>`);$('#asset-right-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{a.rights=$('#assetRights').value;a.source=$('#assetSource').value;a.until=$('#assetUntil').value;a.territory=$('#assetTerritory').value;if(a.source&&!safeURL(a.source))throw Error('URL inválida.');await put('assets',a);const owner=state.productions.find(p=>p.id===a.productionId);if(owner){owner.approval=null;await put('productions',owner);}await audit('asset_rights_updated',a.id);$('#dialog').close();await refresh();render();toast('Licença do ativo registrada.');});};};
actions['export-production']=async b=>{const p=state.productions.find(p=>p.id===b.dataset.id),s=songOf(p);toast('Organizando arquivos…');const blob=await editingPackage(p,s,assetsOf(p.id),pubsOf(p.id));download(blob,`GMM_${slug(s.artist+'_'+s.title)}_V${p.version}.zip`);await audit('editing_package_exported',p.id);toast('Pacote para edição exportado.');};
actions['folder-manifest']=b=>{const p=state.productions.find(p=>p.id===b.dataset.id),s=songOf(p);showDialog(`<h2>Estrutura da produção</h2><p>${esc(s.artist+' — '+s.title)} · V${p.version}</p><pre class="code">GOLDEN_MUSIC_MEMORIES/\n${Object.values(ASSET_FOLDERS).filter((v,i,a)=>a.indexOf(v)===i).map(x=>'  '+x+'/').join('\n')}</pre><p>As pastas são incluídas no pacote ZIP. Não representam pastas já criadas no Google Drive.</p>`);};
actions['cancel-production']=async b=>{const p=state.productions.find(p=>p.id===b.dataset.id);if(assetsOf(p.id).some(a=>['tiktok','youtube'].includes(a.role))||pubsOf(p.id).some(pub=>pub.status==='published'))throw Error('Esta música já possui vídeo final ou publicação. Preserve o histórico e use Criar nova versão.');if(!confirm('Cancelar esta produção e liberar a música? Arquivos e histórico serão preservados.'))return;p.cancelled=true;p.cancelledAt=now();p.status=8;await put('productions',p);await put('reservations',{id:canonicalKey(songOf(p)),songId:p.songId,status:'cancelled',cancelledAt:now()});await audit('production_cancelled',p.id);signal();await route('production');toast('Produção cancelada; música liberada para seleção.');};
actions['new-version']=async b=>{const prev=state.productions.find(p=>p.id===b.dataset.id);const p=await createProduction(prev.songId,prev);route('production',p.id);toast('Nova versão criada. Anteriores preservadas; permissões voltaram a pendentes.');};
actions['cover-production']=async b=>{const p=state.productions.find(p=>p.id===b.dataset.id),s=songOf(p);state.coverProd=p.id;const previous=assetsOf(p.id).filter(a=>a.role==='cover'&&a.coverConfig).at(-1);state.cover={title:s.title,artist:s.artist,year:p.versionYear||s.year,style:'cassette',format:'vertical',font:104,x:.085,y:.23,text:'#f8f0df',accent:'#edc283',...previous?.coverConfig};state.bg=null;await put('settings',{id:'coverDraft',config:state.cover,productionId:p.id});route('covers');};
actions['variation']=()=>{state.cover.y=[.20,.25,.30][Math.floor(Math.random()*3)];state.cover.accent=['#edc283','#d9a441','#bbd9d0','#ffe8b4'][Math.floor(Math.random()*4)];render();};
actions['download-cover']=async()=>{readCover();download(await coverBlob(),slug(state.cover.title)+'_GMM.png');toast('PNG gerado nas dimensões selecionadas.');};actions['download-jpg']=async()=>{readCover();download(await coverBlob('image/jpeg'),slug(state.cover.title)+'_GMM.jpg');toast('JPG gerado nas dimensões selecionadas.');};
actions['approve-cover']=async()=>{readCover();if(!state.coverProd)throw Error('Escolha uma produção para guardar a capa.');const blob=await coverBlob();await uploadFiles([new File([blob],slug(state.cover.title)+'.png',{type:'image/png'})],'cover',state.coverProd);const a=assetsOf(state.coverProd).filter(a=>a.role==='cover').at(-1);a.coverConfig={...state.cover,safe:false};a.rights=state.cover.backgroundAssetId?'pending':'confirmed';await put('assets',a);await put('settings',{id:'coverDraft',config:state.cover,productionId:state.coverProd});await audit('cover_approved',state.coverProd,a.id);toast('Capa aprovada e guardada como nova versão.');};
actions['canva-csv']=()=>{const selected=state.songs.filter(s=>state.selected.has(s.id));if(!selected.length)throw Error('Selecione as músicas para o lote do Canva.');const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const rows=[['ID','MUSICA','ARTISTA','ANO','DECADA','MARCA'],...selected.map(s=>[s.id,s.title,s.artist,s.year,s.decade,'Golden Music Memories'])];download(new Blob(['\uFEFF'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'GMM_CANVA_LOTE.csv');toast('CSV exportado. No Canva, use Criação em lote e conecte as colunas ao seu template.');};
actions['pub-list']=()=>{state.pubLayout='list';render();};actions['pub-kanban']=()=>{state.pubLayout='kanban';render();};actions['pub-calendar']=()=>{state.pubLayout='calendar';render();};
actions['edit-publication']=b=>publicationDialog(b.dataset.id,b.dataset.platform);actions['edit-pub-id']=b=>{const pub=state.publications.find(p=>p.id===b.dataset.id);publicationDialog(pub.productionId,pub.platform,pub);};
function publicationDialog(pid,platform,existing){const p=state.productions.find(p=>p.id===pid),s=songOf(p);const pub=existing||state.publications.find(q=>q.productionId===pid&&q.platform===platform&&['draft','planned'].includes(q.status))||{id:uid(),productionId:pid,platform,status:'draft',title:`${s.title} — ${s.artist}`,description:`${s.title}, de ${s.artist}. Qual lembrança essa música traz para você? Golden Music Memories.`,hashtags:`#GoldenMusicMemories #Anos${String(s.decade).slice(2)} #NostalgiaMusical`,metrics:{}};const finals=assetsOf(pid).filter(a=>a.role===platform);showDialog(`<h2>${platform==='tiktok'?'TikTok':'YouTube'} · V${p.version}</h2><form id="publication-form">${input('pubTitle','Título',pub.title,'text','required')}${select('finalAssetId','Vídeo final desta plataforma',{'':'Selecionar arquivo',...Object.fromEntries(finals.map(a=>[a.id,a.originalName+' · V'+a.version]))},pub.finalAssetId)}<label class="field">Descrição<textarea id="pubDescription">${esc(pub.description)}</textarea></label>${input('hashtags','Hashtags',pub.hashtags)}${publicationOptions(pub)}<div id="publication-video"></div><div class="actions">${btn('copy-field','Copiar título','data-field="pubTitle"','secondary small')}${btn('copy-field','Copiar descrição','data-field="pubDescription"','secondary small')}${btn('copy-field','Copiar hashtags','data-field="hashtags"','secondary small')}</div><div class="form-grid">${input('plannedAt','Data planejada (horário deste dispositivo)',pub.plannedAt||'','datetime-local')}${input('publishedAt','Data efetiva',pub.publishedAt||'','datetime-local')}${select('pubStatus','Situação',{draft:'Rascunho',planned:'Planejada (manual)',published:'Publicada',archived:'Arquivada'},pub.status)}${input('pubURL','Link da publicação',pub.url||'','url')}</div><details><summary>Métricas manuais</summary><div class="form-grid">${['views','likes','comments','shares'].map((k,i)=>input('metric-'+k,['Visualizações','Curtidas','Comentários','Compartilhamentos'][i],pub.metrics?.[k]||0,'number','min="0"')).join('')}</div></details><p class="notice">Salvar não publica nem agenda na plataforma. ${rightsIssues(p,platform).length} pendências de direitos registradas.</p><button type="submit">Salvar registro</button></form>`);const previewFinal=()=>{const a=finals.find(a=>a.id===$('#finalAssetId').value);$('#publication-video').innerHTML=a?`<video controls preload="metadata" src="${mediaURL(a)}" aria-label="Prévia do vídeo final"></video>`:'';};$('#finalAssetId').onchange=previewFinal;previewFinal();$('#publication-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{const next={...pub,title:$('#pubTitle').value,description:$('#pubDescription').value,hashtags:$('#hashtags').value,plannedAt:$('#plannedAt').value,publishedAt:$('#publishedAt').value,status:$('#pubStatus').value,url:$('#pubURL').value,finalAssetId:$('#finalAssetId').value,options:readPublicationOptions(platform),updatedAt:now(),metrics:Object.fromEntries(['views','likes','comments','shares'].map(k=>[k,Math.max(0,Number($('#metric-'+k).value)||0)]))};if(next.url&&!safeURL(next.url))throw Error('Informe um link http ou https válido.');if(next.status==='published'&&(!next.url||!next.publishedAt||!next.finalAssetId))throw Error('Para registrar como publicada, informe vídeo final, data efetiva e URL.');if(next.url&&state.publications.some(x=>x.id!==next.id&&x.url===next.url))throw Error('Este link já está registrado em outra publicação.');if(next.status==='published'&&rightsIssues(p,platform).length){if(!confirm('Há pendências de direitos. Registrar apenas o fato de uma publicação manual já realizada? Esta decisão ficará no histórico.'))return;next.rightsOverrideAt=now();}await put('publications',next);await audit('publication_saved',next.id,next.status);$('#dialog').close();await refresh();render();toast('Registro salvo. Nenhum envio automático foi realizado.');});};}
actions['copy-field']=b=>copy($('#'+b.dataset.field).value);actions['copy-publication']=b=>copy(state.publications.find(p=>p.id===b.dataset.id).description);async function copy(text){try{await navigator.clipboard.writeText(text);toast('Texto copiado.');}catch{showDialog(`<h2>Copiar texto</h2><textarea style="width:100%;height:180px">${esc(text)}</textarea>`);}}
actions['export-backup']=async()=>{toast('Preparando backup completo…');const result=await exportBackup();download(result.blob,'GMM_BACKUP_'+today()+'.zip');await put('settings',{id:'lastBackup',at:now(),files:result.manifest.tables.assets.length});toast('Backup completo exportado. Guarde uma cópia fora do navegador.');};$('#quick-backup').onclick=()=>guarded(actions['export-backup']);
actions['export-records']=()=>download(new Blob([JSON.stringify({schema:2,songs:state.songs,productions:state.productions,publications:state.publications},null,2)],{type:'application/json'}),'GMM_CONTROLE_'+today()+'.json');
actions['drive-structure']=async()=>{const zip=new JSZip(),base=zip.folder('GOLDEN_MUSIC_MEMORIES');for(const f of ['00_CATALOGO_E_CONTROLE','01_MUSICAS_ANOS_70','02_MUSICAS_ANOS_80','03_MUSICAS_ANOS_90','04_MUSICAS_ANOS_2000','05_TEMPLATES','06_BACKUPS_E_EXPORTACOES'])base.folder(f);base.file('LEIA-ME.txt','Estrutura para upload manual no Google Drive. Nenhuma sincronização automática está ativa. Os pacotes de produção contêm arquivos e manifesto.');download(await zip.generateAsync({type:'blob'}),'GMM_ESTRUTURA_DRIVE.zip');};
actions['persist-storage']=async()=>{const ok=await navigator.storage?.persist?.();toast(ok?'O navegador concedeu armazenamento persistente. Mantenha backups externos.':'O navegador não concedeu persistência. Mantenha backups externos.');};
document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(b){e.preventDefault();guarded(async()=>{b.disabled=true;try{await actions[b.dataset.action]?.(b);}finally{b.disabled=false;}});}const nav=e.target.closest('button[data-view]');if(nav)guarded(()=>route(nav.dataset.view));});
window.addEventListener('hashchange',()=>{const [view,id]=location.hash.slice(1).split('/');if(view in TITLES&&(view!==state.view||(id||null)!==state.active))guarded(()=>route(view,id));});
async function init(){await refresh();if(!state.settings.some(s=>s.id==='catalogSeed')){try{const r=await fetch('data/catalog.json');if(!r.ok)throw Error('Catálogo indisponível');const catalog=await r.json();await importSongs(catalog.songs);await put('settings',{id:'catalogSeed',at:now(),count:catalog.count,notes:catalog.notes});}catch(e){toast('Não foi possível carregar o catálogo. Você pode importar registros reais.');}}await refresh();state.selected=new Set((state.reservations||[]).filter(r=>r.status==='reserved').map(r=>r.songId));const [view,id]=location.hash.slice(1).split('/');state.view=view in TITLES?view:'dashboard';state.active=id||null;await render();if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}
if(channel)channel.onmessage=()=>{guarded(async()=>{await refresh();if(['catalog','dashboard','production','publications','archive'].includes(state.view)&&!state.active)render();});};
init().catch(e=>{$('#store-status').textContent='Armazenamento indisponível';$('#main').textContent='Não foi possível abrir o banco local. Use uma janela normal do navegador com armazenamento habilitado. '+e.message;});

async function selectTemplate(id){clearTimeout(coverTimer);readCover();state.cover={...state.cover,...templatePreset(id)};delete state.cover.backgroundAssetId;state.bg=null;await put('settings',{id:'coverDraft',config:state.cover,productionId:state.coverProd});await render();}
actions['select-template']=b=>selectTemplate(b.dataset.id);

let searchTimer;
async function rememberSearch(){const q=state.search.trim();if(!q)return;const old=state.settings.find(s=>s.id==='searchHistory')?.queries||[];const record={id:'searchHistory',queries:[q,...old.filter(v=>v!==q)].slice(0,8)};await put('settings',record);state.settings=state.settings.filter(s=>s.id!==record.id).concat(record);}
function bindCatalog(){const search=$('#catalog-search');if(!search)return;
 search.oninput=()=>{state.search=search.value;state.page=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>guarded(async()=>{const pos=search.selectionStart;await render();const current=$('#catalog-search');if(current){current.focus();try{current.setSelectionRange(pos,pos);}catch{}}}),180);};
 search.onchange=()=>guarded(rememberSearch);search.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(searchTimer);guarded(async()=>{state.search=search.value;await rememberSearch();await render();$('#catalog-search')?.focus();});}};
 $('#advanced-filters').ontoggle=e=>{if(e.target.isConnected)state.advanced=e.target.open;};
 for(const el of document.querySelectorAll('[id^="filter-"]'))el.onchange=()=>{const key=el.id.slice(7);if(state.filters[key]===el.value)return;clearTimeout(searchTimer);state.filters[key]=el.value;state.page=0;render();};
}
actions['clear-filters']=()=>{clearTimeout(searchTimer);Object.assign(state,{search:'',decade:'',repertoire:'',favorites:false,unused:false,filters:{},page:0});render();};
actions['recent-search']=b=>{state.search=b.dataset.query;state.page=0;render();};
actions['metadata-search']=()=>showDialog(`<h2>Consultar metadados</h2><p>Pesquise a gravação na fonte e confira artista, versão e ano antes de cadastrar. Esta consulta abre o MusicBrainz; o catálogo local continua disponível offline.</p><a href="${esc(musicBrainzSearchURL(state.search))}" target="_blank" rel="noopener noreferrer">Abrir pesquisa no MusicBrainz</a><p class="muted">A fonte fornece metadados. Não autoriza o download da música. A consulta automática ainda depende da configuração de uso do serviço.</p>`);
actions['recover-cover']=async b=>{const a=state.assets.find(a=>a.id===b.dataset.id);if(!a?.coverConfig)return;state.cover={...a.coverConfig};state.coverProd=a.productionId;state.bg=null;await put('settings',{id:'coverDraft',config:state.cover,productionId:a.productionId});await route('covers');};
function publicationOptions(pub){const o=pub.options||{};return `<details class="publication-options"><summary>Opções do ${pub.platform==='youtube'?'YouTube':'TikTok'}</summary><div class="form-grid">${select('pubPrivacy','Privacidade (preparação)',pub.platform==='youtube'?{private:'Privado',unlisted:'Não listado',public:'Público'}:{'':'Escolher quando conectar',SELF_ONLY:'Somente eu'},o.privacy||'private')}${pub.platform==='youtube'?input('pubCategory','Categoria (YouTube)',o.categoryId||'10')+input('pubTags','Tags separadas por vírgula',(o.tags||[]).join(', ')):''}</div>${pub.platform==='youtube'?`<label><input type="checkbox" id="pubKids" ${o.madeForKids?'checked':''}> Conteúdo destinado a crianças</label><br><label><input type="checkbox" id="pubSynthetic" ${o.containsSyntheticMedia?'checked':''}> Conteúdo alterado ou sintético a declarar</label>`:`${[['allowComment','Permitir comentários'],['allowDuet','Permitir Dueto'],['allowStitch','Permitir Costura'],['commercialContent','Conteúdo comercial'],['musicUsageConsent','Confirmei o uso autorizado da música']].map(([id,label])=>`<label><input type="checkbox" id="pub-${id}" ${o[id]?'checked':''}> ${label}</label><br>`).join('')}`}<small>Opções preparadas localmente. Disponibilidade e permissões deverão ser confirmadas pela plataforma conectada.</small></details>`;}
function readPublicationOptions(platform){return platform==='youtube'?{privacy:$('#pubPrivacy').value,categoryId:$('#pubCategory').value,tags:$('#pubTags').value.split(',').map(s=>s.trim()).filter(Boolean),madeForKids:$('#pubKids').checked,containsSyntheticMedia:$('#pubSynthetic').checked}:{privacy:$('#pubPrivacy').value,...Object.fromEntries(['allowComment','allowDuet','allowStitch','commercialContent','musicUsageConsent'].map(k=>[k,$('#pub-'+k).checked]))};}
function deliveryPanel(pubs){return `<details class="panel delivery-panel"><summary>Preparação de envio e testes locais</summary><p class="muted">Contas desconectadas · envio real desabilitado. Simulações não publicam nem alteram métricas.</p>${pubs.map(pub=>`<article class="delivery-item"><div><b>${esc(pub.title)}</b><small>${esc(pub.platform)} · ${esc(deliveryLabel(pub))}</small>${pub.delivery?.envelope?.account?`<small>Destino de teste: ${esc(pub.delivery.envelope.account.label||pub.delivery.envelope.account.id||'Simulado')}</small>`:''}${pub.delivery?.issues?.length?`<ul>${pub.delivery.issues.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`:''}${pub.delivery?.error?`<p role="status">${esc(pub.delivery.error.message||pub.delivery.error)}</p>`:''}</div><div class="actions">${btn('prepare-delivery','Conferir preparação',`data-id="${pub.id}"`,'secondary small')}${btn('simulate-delivery','Testar simulação',`data-id="${pub.id}"`,'secondary small')}${pub.delivery?btn('cancel-delivery','Cancelar teste',`data-id="${pub.id}"`,'link small'):''}${btn('open-production','Abrir produção',`data-id="${pub.productionId}"`,'link small')}${btn('export-production','Pacote manual',`data-id="${pub.productionId}"`,'link small')}</div></article>`).join('')||'<p>Prepare uma publicação dentro de uma produção para conferir seu envio.</p>'}</details>`;}
actions['prepare-delivery']=async b=>{const pub=state.publications.find(p=>p.id===b.dataset.id);await prepareDelivery(pub,state.productions.find(p=>p.id===pub.productionId),assetsOf(pub.productionId));await refresh();await render();$('.delivery-panel').open=true;};
actions['simulate-delivery']=b=>{const pub=state.publications.find(p=>p.id===b.dataset.id);showDialog(`<h2>Simulação de ${pub.platform==='youtube'?'YouTube':'TikTok'}</h2><p>Conta de teste local. Nenhum arquivo será enviado a uma plataforma.</p>${select('simulation-scenario','Cenário',{success:'Envio concluído',network:'Falha de conexão (permite repetir)',rejected:'Rejeição do provedor',revoked:'Permissão revogada'},'success')}<button id="run-simulation">Aprovar e executar teste</button>`);$('#run-simulation').onclick=()=>guarded(async()=>{const scenario=$('#simulation-scenario').value;let current=state.publications.find(p=>p.id===pub.id);if(!(current.delivery?.state==='failed'&&current.delivery?.error?.retryable)){current=await prepareDelivery(current,state.productions.find(p=>p.id===pub.productionId),assetsOf(pub.productionId),{id:'simulation:'+pub.platform,platform:pub.platform,mode:'simulation',label:'Conta de teste local'});}if(current.delivery.state==='simulation_ready'||current.delivery.state==='failed')await runSimulation(current,scenario);$('#dialog').close();await refresh();await render();$('.delivery-panel').open=true;toast('Resultado do teste registrado separadamente da publicação manual.');});};
actions['cancel-delivery']=async b=>{await cancelDelivery(state.publications.find(p=>p.id===b.dataset.id));await refresh();await render();$('.delivery-panel').open=true;};


